BeatHistory.customGLSL:
/* @node beatHistory
   @title Beat History
   @input uv "UV"
   @input prev "Previous"
   @description Scrolling record of the beat tracker: each frame shifts one column left and writes the newest values in the right-most column. Row 0 = (kick, raw beat phase, raw bar phase, confidence) of the tracker's live estimate (u_beatRaw), row 1 = (level, bass, mid, high), row 2 = (stable beat phase, stable bar phase, trust, 0) of the published clock shaders see. Feed into a 512x3 rgba16f / nearest Feedback node. */
vec4 beatHistory(vec2 uv, sampler2D prev) {
    ivec2 size = textureSize(prev, 0);
    ivec2 px = ivec2(floor(uv * vec2(size)));
    if (px.x < size.x - 1) return texelFetch(prev, px + ivec2(1, 0), 0);
    if (px.y == 0) return vec4(u_kick, u_beatRaw.x, u_beatRaw.y, u_beatConfidence);
    if (px.y == 1) return vec4(u_level, u_bass, u_mid, u_high);
    return vec4(u_beatPhase, u_barPhase, u_beatTrust, 0.0);
}

BeatLabDisplay.customGLSL:
/* @node beatLab
   @title Beat Lab Display
   @input uv "UV"
   @input hist "History"
   @description Diagnostic view of the beat tracker: the raw (live) estimate as beat pulse + phase hand, kick flash, BPM readout and confidence; the stable published clock as a green hand, green BPM readout and trust bar; band meters and a scrolling timeline (kicks vs. the raw beat grid, stable beats in green). */

float bl_box(vec2 p, vec2 b) { vec2 d = abs(p) - b; return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0); }

// 7-segment digit, cell about [-0.5,0.5] x [-1,1]; returns a signed distance
float bl_digit(vec2 p, int d) {
    int bits = d == 0 ? 0x3F : d == 1 ? 0x06 : d == 2 ? 0x5B : d == 3 ? 0x4F : d == 4 ? 0x66 :
               d == 5 ? 0x6D : d == 6 ? 0x7D : d == 7 ? 0x07 : d == 8 ? 0x7F : 0x6F;
    float w = 0.085, m = 1e3;
    if ((bits & 1) != 0)  m = min(m, bl_box(p - vec2(0.0, 0.9), vec2(0.34, w)));
    if ((bits & 2) != 0)  m = min(m, bl_box(p - vec2(0.42, 0.45), vec2(w, 0.34)));
    if ((bits & 4) != 0)  m = min(m, bl_box(p - vec2(0.42, -0.45), vec2(w, 0.34)));
    if ((bits & 8) != 0)  m = min(m, bl_box(p - vec2(0.0, -0.9), vec2(0.34, w)));
    if ((bits & 16) != 0) m = min(m, bl_box(p - vec2(-0.42, -0.45), vec2(w, 0.34)));
    if ((bits & 32) != 0) m = min(m, bl_box(p - vec2(-0.42, 0.45), vec2(w, 0.34)));
    if ((bits & 64) != 0) m = min(m, bl_box(p, vec2(0.34, w)));
    return m;
}

vec3 bl_lockColor(float c) {
    return c > 0.8 ? vec3(0.29, 0.87, 0.5) : (c > 0.4 ? vec3(0.96, 0.78, 0.29) : vec3(0.95, 0.33, 0.33));
}

vec3 beatLab(vec2 uv, sampler2D hist) {
    // Layout lives in a 1.6 x 1 design space, fitted (letterboxed) into any canvas shape
    float aspect = u_resolution.x / u_resolution.y;
    float fit = min(1.0, aspect / 1.6);
    vec2 q = (vec2(uv.x * aspect, uv.y) - vec2(aspect * 0.5, 0.5)) / fit + vec2(0.8, 0.5);
    float px = 1.5 / (u_resolution.y * fit);
    float conf = clamp(u_beatConfidence, 0.0, 1.0);
    float trust = clamp(u_beatTrust, 0.0, 1.0);
    // Raw clock: the tracker's live estimate (Beat node clock = raw); the stable clock is u_beatPhase...
    float rph = u_beatRaw.x;
    float rpulse = exp(-6.0 * rph);
    int beatInBar = int(floor(fract(u_beatRaw.y) * 4.0));
    bool downbeat = beatInBar == 0;
    vec3 stableCol = vec3(0.35, 0.95, 0.55);

    vec3 col = vec3(0.045, 0.05, 0.065) + 0.02 * rpulse * conf;

    // ---- Beat circle + phase hand --------------------------------------
    vec2 bc = vec2(0.36, 0.67);
    float r0 = 0.12 + 0.045 * rpulse;
    float d = length(q - bc);
    vec3 beatCol = downbeat ? vec3(1.0, 0.45, 0.17) : vec3(0.35, 0.8, 1.0);
    float body = 1.0 - smoothstep(r0 - px, r0 + px, d);
    col = mix(col, beatCol * (0.18 + 0.82 * rpulse) * mix(0.35, 1.0, conf), body);
    // ring track + phase arc (12 o'clock = the beat)
    float ang = atan(q.x - bc.x, q.y - bc.y) / 6.2831853;
    ang = fract(ang);
    float ring = 1.0 - smoothstep(0.004 - px, 0.004 + px, abs(d - 0.205));
    col = mix(col, vec3(0.16, 0.18, 0.22), ring);
    float arc = ring * step(ang, rph);
    col = mix(col, vec3(0.85, 0.9, 1.0) * mix(0.5, 1.0, conf), arc);
    // stable (published) clock: green hand just outside the ring, bright as far as it is trusted
    vec2 shand = bc + 0.232 * vec2(sin(6.2831853 * u_beatPhase), cos(6.2831853 * u_beatPhase));
    col = mix(col, stableCol * mix(0.4, 1.0, trust), 1.0 - smoothstep(0.011 - px, 0.011 + px, length(q - shand)));
    vec2 hand = bc + 0.205 * vec2(sin(6.2831853 * rph), cos(6.2831853 * rph));
    col = mix(col, vec3(1.0), 1.0 - smoothstep(0.014 - px, 0.014 + px, length(q - hand)));
    // top tick: where the beat lands
    col = mix(col, vec3(1.0, 0.45, 0.17), 1.0 - smoothstep(-px, px, bl_box(q - (bc + vec2(0.0, 0.235)), vec2(0.004, 0.018))));
    // bar dots
    for (int i = 0; i < 4; i++) {
        vec2 c = vec2(bc.x + (float(i) - 1.5) * 0.07, 0.42);
        float on = i == beatInBar ? 1.0 : 0.0;
        vec3 dc = i == 0 ? vec3(1.0, 0.45, 0.17) : vec3(0.35, 0.8, 1.0);
        float m = 1.0 - smoothstep(0.016 - px, 0.016 + px, length(q - c));
        col = mix(col, mix(vec3(0.14, 0.15, 0.19), dc * (0.6 + 0.4 * rpulse), on), m);
    }

    // ---- Kick flash (compare its timing with the beat circle) ----------
    vec2 kc = vec2(0.82, 0.67);
    float kr = 0.06 + 0.035 * u_kick;
    float km = 1.0 - smoothstep(kr - px, kr + px, length(q - kc));
    col = mix(col, mix(vec3(0.12, 0.08, 0.06), vec3(1.0, 0.55, 0.2), clamp(u_kick, 0.0, 1.0)), km);
    float kring = 1.0 - smoothstep(0.003 - px, 0.003 + px, abs(length(q - kc) - 0.1));
    col = mix(col, vec3(0.22, 0.16, 0.12), kring);

    // ---- BPM readout (7-segment) ---------------------------------------
    // raw (tracker) tempo large, stable (published) tempo small and green below it
    for (int k = 0; k < 2; k++) {
        float bpm = clamp(k == 0 ? u_beatRaw.w : u_bpm, 0.0, 999.9);
        int tenths = int(floor(bpm * 10.0 + 0.5));
        int dg[4];
        dg[0] = (tenths / 1000) % 10; dg[1] = (tenths / 100) % 10; dg[2] = (tenths / 10) % 10; dg[3] = tenths % 10;
        vec2 o = k == 0 ? vec2(1.08, 0.80) : vec2(1.10, 0.645);
        float sz = k == 0 ? 0.075 : 0.042;
        float sp = k == 0 ? 0.097 : 0.055;
        vec3 numCol = k == 0 ? mix(vec3(0.45, 0.48, 0.55), vec3(0.95, 0.97, 1.0), conf) : stableCol * mix(0.45, 1.0, trust);
        for (int i = 0; i < 4; i++) {
            if (i == 0 && dg[0] == 0) continue;
            float x = o.x + float(i) * sp + (i == 3 ? sp * 0.45 : 0.0);
            float sd = bl_digit((q - vec2(x, o.y)) / sz, dg[i]) * sz;
            col = mix(col, numCol, 1.0 - smoothstep(-px, px, sd));
        }
        col = mix(col, numCol, 1.0 - smoothstep(sz * 0.14 - px, sz * 0.14 + px, length(q - vec2(o.x + sp * 2.72, o.y - sz * 0.9))));
    }

    // ---- Confidence bar ----------------------------------------------
    vec2 cb0 = vec2(1.03, 0.55), cbs = vec2(0.5, 0.022);
    float inBar = 1.0 - smoothstep(-px, px, bl_box(q - (cb0 + cbs * 0.5), cbs * 0.5));
    float fill = step(q.x, cb0.x + cbs.x * conf);
    col = mix(col, mix(vec3(0.12, 0.13, 0.16), bl_lockColor(conf), fill), inBar);
    // trust bar (u_beatTrust: how far the published clock follows the estimate), thin, green
    vec2 tb0 = vec2(1.03, 0.585), tbs = vec2(0.5, 0.01);
    float inT = 1.0 - smoothstep(-px, px, bl_box(q - (tb0 + tbs * 0.5), tbs * 0.5));
    col = mix(col, mix(vec3(0.1, 0.12, 0.11), stableCol, step(q.x, tb0.x + tbs.x * trust)), inT);

    // ---- Band meters: level, bass, mid, high --------------------------
    vec4 bands = vec4(u_level, u_bass, u_mid, u_high);
    vec3 bandCol[4];
    bandCol[0] = vec3(0.4, 0.9, 0.7); bandCol[1] = vec3(1.0, 0.45, 0.25); bandCol[2] = vec3(0.98, 0.82, 0.35); bandCol[3] = vec3(0.55, 0.75, 1.0);
    for (int i = 0; i < 4; i++) {
        vec2 b0 = vec2(1.03, 0.49 - float(i) * 0.03), bs = vec2(0.5, 0.014);
        float m = 1.0 - smoothstep(-px, px, bl_box(q - (b0 + bs * 0.5), bs * 0.5));
        float f = step(q.x, b0.x + bs.x * clamp(bands[i], 0.0, 1.0));
        col = mix(col, mix(vec3(0.1, 0.11, 0.14), bandCol[i], f), m);
    }

    // ---- Timeline: kicks vs. the beat grid (newest on the right) -------
    float x0 = 0.05, x1 = 1.55, y0 = 0.05, y1 = 0.33;
    if (q.x > x0 && q.x < x1 && q.y > y0 - 0.02 && q.y < y1 + 0.02) {
        ivec2 hs = textureSize(hist, 0);
        float hx = (q.x - x0) / (x1 - x0);
        int ix = clamp(int(hx * float(hs.x)), 1, hs.x - 1);
        vec4 a = texelFetch(hist, ivec2(ix, 0), 0);
        vec4 prev = texelFetch(hist, ivec2(ix - 1, 0), 0);
        vec4 bnd = texelFetch(hist, ivec2(ix, 1), 0);
        vec4 st = texelFetch(hist, ivec2(ix, 2), 0);
        vec4 stPrev = texelFetch(hist, ivec2(ix - 1, 2), 0);
        float h = (q.y - y0) / (y1 - y0);
        vec3 tl = vec3(0.07, 0.075, 0.095);
        if (h < 0.0) {
            tl = stableCol * (0.15 + 0.85 * st.z);                                  // trust strip
        } else if (h <= 1.0) {
            tl = mix(tl, vec3(0.16, 0.22, 0.4), step(h, bnd.y * 0.7));          // bass area
            tl = mix(tl, vec3(1.0, 0.55, 0.2), step(h, clamp(a.x, 0.0, 1.0)) * 0.9); // kick spikes
            bool beatTick = a.y < prev.y - 0.5;                                     // beat phase wrapped
            bool barTick = a.z < prev.z - 0.5;
            if (beatTick) tl = mix(tl, barTick ? vec3(1.0, 0.85, 0.6) : vec3(0.9, 0.95, 1.0), mix(0.35, 1.0, a.w));
            // stable (published) beats: green ticks in the lower quarter
            if (h < 0.25 && st.x < stPrev.x - 0.5) tl = stableCol * mix(0.4, 1.0, st.z);
        } else {
            tl = bl_lockColor(a.w) * (0.35 + 0.65 * a.w);                          // confidence strip
        }
        col = tl;
    }
    // "now" marker
    col = mix(col, vec3(1.0), (1.0 - smoothstep(-px, px, bl_box(q - vec2(x1 + 0.008, (y0 + y1) * 0.5), vec2(0.002, (y1 - y0) * 0.5)))) * 0.6);

    return col;
}
